Let $v\neq r$ be a vertex such that $M(B(v)\setminus\{e_L(v)\})\neq M(v)$, and let $u$ be a proper descendant of $v$ with $\mathit{high}(u)=\mathit{high}(v)$. Then, $e_L(v)\notin B(u)$.
\end{lemma}
\begin{proof}
Since $u$ is a proper descendant of $v$ with $\mathit{high}(u)=\mathit{high}(v)$, Lemma~\ref{lemma:same_high} implies that $B(u)\subseteq B(v)$. This implies that $M(u)$ is a descendant of $M(v)$. Thus, since $M(u)$ is a common descendant of $u$ and $M(v)$, we have that $u$ and $M(v)$ are related as ancestor and descendant.

Let us suppose, for the sake of contradiction, that $u$ is not a proper descendant of $M(v)$. Thus, we have that $u$ is an ancestor of $M(v)$. Let $(x,y)$ be a back-edge in $B(v)$. Then, $x$ is a descendant of $M(v)$, and therefore a descendant of $u$. Furthermore, $y$ is a proper ancestor of $v$, and therefore a proper ancestor of $u$. This shows that $(x,y)\in B(u)$. Due to the generality of $(x,y)\in B(v)$, this implies that $B(v)\subseteq B(u)$. Thus, $B(u)\subseteq B(v)$ implies that $B(u)=B(v)$, in contradiction to the fact that the graph is $3$-edge-connected. This shows that $u$ is a proper descendant of $M(v)$.

Now let us suppose, for the sake of contradiction, that $u$ is an ancestor of $L_1(v)$ (i.e., the higher endpoint of $e_L(v)$). Then, since $u$ is a proper descendant of $M(v)$, we cannot have $M(v)=L_1(v)$. Thus, $L_1(v)$ is a proper descendant of $M(v)$. So let $c$ be the child of $M(v)$ that is an ancestor of $L_1(v)$. Then, since $M(B(v)\setminus\{e_L(v)\})\neq M(v)$, we have that $e_L(v)$ is the unique back-edge in $B(v)$ whose higher endpoint is a descendant of $c$. Now, since $u$ is an ancestor of $L_1(v)$ and a proper descendant of $M(v)$, we have that $u$ is also a descendant of $c$. Since the graph is $3$-edge-connected, we have that $|B(u)|>1$. Thus, there is a back-edge $(x,y)\in B(u)\setminus\{e_L(v)\}$. Then, $x$ is a descendant of $u$, and therefore a descendant of $v$. Furthermore, $y$ is an ancestor of $\mathit{high}(u)=\mathit{high}(v)$, and therefore a proper ancestor of $v$. This shows that $(x,y)\in B(v)$. Since $(x,y)\neq e_L(v)$, this can be strengthened to $(x,y)\in B(v)\setminus\{e_L(v)\}$. Thus, we have that in $B(v)\setminus\{e_L(v)\}$ there is still a back-edge whose higher endpoint is a descendant of $c$ (i.e., $(x,y)$), which is impossible. We conclude that $u$ is not an ancestor of $L_1(v)$, and therefore $e_L(v)\notin B(u)$. 
\end{proof}

\begin{lemma}
\label{lemma:type3-b-ii-4-seg-2}
Let $(u,v,w)$ be a triple of vertices that induces a Type-3$\beta$ii-$4$ $4$-cut, such that $M(B(v)\setminus\{e\})\neq M(v)$, where $e$ is the back-edge in the $4$-cut induced by $(u,v,w)$. Let $u'$ be a vertex in $H(\mathit{high}_1(v))$ such that $u\geq u'\geq v$. Then $u'$ is an ancestor of $u$. 
